import React from 'react';

export default function Nav({ page, setPage }) {
  const links = [
    { id:'home',      label:'Hem' },
    { id:'checkin',   label:'Check-in' },
    { id:'history',   label:'Historik' },
    { id:'breathing', label:'Andning' },
  ];

  return (
    <nav style={{
      position:'fixed', top:0, left:0, right:0, zIndex:100,
      display:'flex', alignItems:'center', justifyContent:'space-between',
      padding:'0 28px', height:56,
      background:'rgba(14,14,18,0.7)',
      backdropFilter:'blur(20px)',
      borderBottom:'1px solid rgba(255,255,255,0.06)',
    }}>
      <button onClick={() => setPage('home')} style={{
        fontSize:15, fontWeight:700, letterSpacing:'-0.02em', color:'#fff',
        display:'flex', alignItems:'center', gap:8,
      }}>
        <span style={{ fontSize:18 }}></span> Spiral
      </button>
      <div style={{ display:'flex', gap:4 }}>
        {links.map(l => (
          <button key={l.id} onClick={() => setPage(l.id)} style={{
            padding:'6px 14px', borderRadius:8, fontSize:12, fontWeight:500,
            color: page === l.id ? '#fff' : 'rgba(255,255,255,0.4)',
            background: page === l.id ? 'rgba(255,255,255,0.08)' : 'transparent',
            transition:'all .2s',
          }}>
            {l.label}
          </button>
        ))}
      </div>
    </nav>
  );
}
